messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Three.js Car Race</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #87CEEB; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="module">
        import * as THREE from './three.module.js';

        // Scene setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB);
        scene.fog = new THREE.Fog(0x87CEEB, 20, 150);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.5, 1000);
        camera.position.set(0, 12, 45);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // Lights
        const ambient = new THREE.AmbientLight(0xffffff, 0.5);
        scene.add(ambient);
        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(50, 100, 50);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        dirLight.shadow.camera.near = 0.5;
        dirLight.shadow.camera.far = 200;
        dirLight.shadow.camera.left = -50;
        dirLight.shadow.camera.right = 50;
        dirLight.shadow.camera.top = 50;
        dirLight.shadow.camera.bottom = -50;
        scene.add(dirLight);

        // Ground
        const planeGeo = new THREE.PlaneGeometry(2000, 2000, 64, 64);
        const planeMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.8, metalness: 0.2 });
        const plane = new THREE.Mesh(planeGeo, planeMat);
        plane.rotation.x = -Math.PI / 2;
        plane.receiveShadow = true;
        scene.add(plane);

        // Finish line (striped)
        const finishGeo = new THREE.PlaneGeometry(6, 100);
        const finishMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
        const finishLine = new THREE.Mesh(finishGeo, finishMat);
        finishLine.rotation.x = -Math.PI / 2;
        finishLine.position.set(0, 0.01, -100); // Fixed in world space
        scene.add(finishLine);

        // Car base geometry (simple box with wheel cylinders)
        function createCar(color, position) {
            const group = new THREE.Group();
            group.position.copy(position);

            const bodyGeo = new THREE.BoxGeometry(3, 1.2, 6);
            const bodyMat = new THREE.MeshStandardMaterial({ color: color, roughness: 0.3, metalness: 0.1 });
            const body = new THREE.Mesh(bodyGeo, bodyMat);
            body.castShadow = true;
            body.position.y = 1.2;
            group.add(body);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(0.6, 0.6, 0.4, 24);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.7 });
            const positions = [
                [-1.5, 0.6, 2.2], [1.5, 0.6, 2.2],
                [-1.5, 0.6, -2.2], [1.5, 0.6, -2.2]
            ];
            positions.forEach(pos => {
                const w = new THREE.Mesh(wheelGeo, wheelMat);
                w.rotation.z = Math.PI / 2;
                w.position.set(...pos);
                w.castShadow = true;
                group.add(w);
            });

            // Windshield
            const windshieldGeo = new THREE.BoxGeometry(2.4, 0.7, 0.2);
            const windshieldMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.1, metalness: 0.5 });
            const windshield = new THREE.Mesh(windshieldGeo, windshieldMat);
            windshield.position.set(0, 1.8, 1.1);
            group.add(windshield);

            return group;
        }

        const carRed = createCar(0xff0000, new THREE.Vector3(0, 0, -30));
        const carBlue = createCar(0x0000ff, new THREE.Vector3(0, 0, -20));
        scene.add(carRed);
        scene.add(carBlue);

        // Track markers
        const markerGeo = new THREE.BoxGeometry(10, 1, 1);
        const markerMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
        for (let z = -110; z <= 0; z += 10) {
            const m = new THREE.Mesh(markerGeo, markerMat);
            m.position.set(0, 0.01, z);
            scene.add(m);
        }

        // Animation state
        let raceState = 'start'; // start, race, finish
        const finishZ = -100;
        const cameraZ = 45;
        const cameraY = 12;

        // Resize handler
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Animation loop
        function animate() {
            requestAnimationFrame(animate);

            const dt = 0.016; // approx frame time

            // Camera follows the leading car with smooth interpolation
            const targetZ = raceState === 'finish' ? cameraZ : Math.max(cameraZ, Math.min(finishZ + 10, carRed.position.z));
            camera.position.z += (targetZ - camera.position.z) * 0.1;
            camera.position.y = cameraY;
            camera.lookAt(0, 0, targetZ - 5);

            // Car movement
            if (raceState === 'start') {
                // Blue starts fast, Red starts slow
                carBlue.position.z += 8 * dt;
                carRed.position.z += 2 * dt;
                // Accelerate Red linearly
                carRed.position.z += (2 + Math.sin(Date.now() * 0.001) * 0.5) * dt;
                if (carRed.position.z > carBlue.position.z) {
                    raceState = 'race';
                }
            } else if (raceState === 'race') {
                // Blue maintains speed, Red accelerates
                const blueSpeed = 6;
                const redSpeed = 9 + Math.sin(Date.now() * 0.002) * 1;
                carBlue.position.z += blueSpeed * dt;
                carRed.position.z += redSpeed * dt;

                // Check finish
                if (carRed.position.z >= finishZ) {
                    raceState = 'finish';
                }
            } else if (raceState === 'finish') {
                // Keep cars near finish for a moment, then reset
                carBlue.position.z = Math.min(finishZ - 2, carBlue.position.z);
                carRed.position.z = Math.min(finishZ - 2, carRed.position.z);
                if (carBlue.position.z >= finishZ - 5 && carRed.position.z >= finishZ - 5) {
                    raceState = 'start';
                    carBlue.position.z = -20;
                    carRed.position.z = -30;
                }
            }

            renderer.render(scene, camera);
        }

        animate();
    </script>
</body>
</html>
```
